package app.cryptoresearch.mobile;
import org.junit.*;import static org.junit.Assert.*;import org.junit.runner.RunWith;import org.robolectric.*;import org.robolectric.annotation.*;import org.json.*;import java.nio.charset.StandardCharsets;
@RunWith(RobolectricTestRunner.class) @Config(sdk=28) @LooperMode(LooperMode.Mode.PAUSED)
public class OperationsTests {
 @Test public void boundedReadRoutes(){String id="a".repeat(32);for(String path:new String[]{"api/v1/diagnostics","api/v1/events?limit=50","api/v1/events?limit=50&before=9223372036854775807","api/v1/sessions?limit=100","api/v1/sessions/"+id+"/report"})assertTrue(path,PaperServerAPI.allowedPath(path));for(String path:new String[]{"api/v1/orders","api/v1/events?limit=50&before=0","api/v1/events?limit=50&before=9223372036854775808","api/v1/events?limit=50&before=1&token=x","api/v1/sessions/../report","api/v1/sessions/"+id+"/report?x=1"})assertFalse(path,PaperServerAPI.allowedPath(path));}
 @Test public void operationsPanelDoesNotRequestWhileStopped(){var controller=Robolectric.buildActivity(ServerOperationsActivity.class).create().start();var app=controller.get();assertFalse(app.busy);controller.stop();app.loadCurrent();assertFalse(app.busy);controller.destroy();}
 @Test public void diagnosticValidatesPaperOnly()throws Exception{var controller=Robolectric.buildActivity(ServerOperationsActivity.class).create();var app=controller.get();JSONObject j=new JSONObject().put("mode","SERVER_PAPER_ONLY").put("live_orders_supported",false).put("workers",new JSONObject().put("clock","failed"));app.render("api/v1/diagnostics",j,new byte[0]);assertEquals(1,app.content.getChildCount());j.put("live_orders_supported",true);assertThrows(Exception.class,()->app.render("api/v1/diagnostics",j,new byte[0]));controller.destroy();}
 @Test public void eventPagesAreBoundedAndCursorValidated()throws Exception{var controller=Robolectric.buildActivity(ServerOperationsActivity.class).create();var app=controller.get();JSONArray a=new JSONArray();for(int i=0;i<60;i++)a.put(new JSONObject().put("kind","worker_failed").put("created_ms",1767225600000L).put("detail","fake"));JSONObject j=new JSONObject().put("items",a).put("next_before","5&token=bad");app.render("api/v1/events?limit=50",j,new byte[0]);assertEquals(50,app.content.getChildCount());assertNull(app.nextBefore);controller.destroy();}
}
